assert len(sources) == len(drafts) == 4
answer = []
for source, (filename, reason, review_notes) in zip(sources, drafts):
    entry = {
        key: source[key]
        for key in ("code_id", "source_id", "source_sha256", "number")
    }
    entry.update(
        proposed_xml=Path("fragments", filename).read_text().strip(),
        reason=reason,
        review_notes=review_notes,
        status="rewrite_draft",
    )
    answer.append(entry)

Path("answer.json").write_text(
    json.dumps(answer, ensure_ascii=False, indent=2) + "\n"
)
